			const minDist = (1 - entranceProgress) * path.getTotalLength()
			const maxDist = (1 - exitProgress) * path.getTotalLength()
			const checkpoints = intersections.filter((i) => {
				const minOtherDist = (1 - entranceProgress) * i.other.path.getTotalLength()
				const maxOtherDist = (1 - exitProgress) * i.other.path.getTotalLength()
				return i.under && i.other.distance >= minOtherDist && i.other.distance <= maxOtherDist
			})
