const pathGenerators = {
	flower: (numPoints) => {
		const points = []
		const off = random(TWO_PI)
		const r = random(0.3, 0.5)
		numPoints = numPoints || random([3, 3, 3, 4, 4, 5])
		for (let i = 0; i < numPoints; i++) {
			points.push({
				pt: createVector(
					width*r*cos(i/numPoints*TWO_PI+off),
					width*r*sin(i/numPoints*TWO_PI+off),
				),
			})
		}
		points.push(points[0])
		for (let i = 0; i < numPoints; i++) {
			var curr = points[i]
			const next = points[i + 1]
			const tangent = next.pt.copy().sub(curr.pt).normalize()
			const normal = createVector(-tangent.y, tangent.x).setMag(width * r)
			curr.right = curr.pt.copy().add(normal)
			next.left = next.pt.copy().add(normal)
		}
		return points
	},
	ribbon: () => {
		const srcPath = createBezierPath(random([
			pathGenerators.triangle,
			pathGenerators.circle,
			() => pathGenerators.flower(random() < 0.7 ? 3 : 4),
		])())

		var numSamples = ceil(srcPath.getTotalLength() / 0.5)
		const newSamples = []
		const numLoops = ceil(srcPath.getTotalLength() / 55)
		const distScale = TWO_PI * numLoops / srcPath.getTotalLength()
		for (let i = 0; i < numSamples; i++) {
			var t = i / (numSamples - 1)
			const dist = t * srcPath.getTotalLength()
			const pt = srcPath.getPointAtLength(dist)
			const tan = srcPath.getTangentAtLength(dist)
			var off = new DOMPointReadOnly(
				cos(dist*distScale) * 35,
				sin(dist*distScale*2) * 25
			).matrixTransform(new DOMMatrixReadOnly().rotate(0, 0, 90 + atan2(tan.y, tan.x)/PI*180))
			newSamples.push({ pt: createVector(off.x + pt.x, off.y + pt.y) })
		}

		return smoothLoop(newSamples)
	},
	loops: (arms) => {
		arms = arms || random([2,2,3,3,4])
		const subArms = random([1,1,2,2,3,3,4])
		var loops = 1

		const offX = random(-50, 50)
		const offY = random(-50, 50)

		const epicycles = [
			{
				r: (f) => sin(f*arms*TWO_PI) * 30 + 120,
				k: () => loops,
			},
			{
				r: (f) => sin(f*subArms*TWO_PI) * 25 + 60,
				k: () => 2 * arms
			},
		]

		var points = []
		var numSamples = 300
		const rotOff = random()
		for (let i = 0; i < numSamples; i++) {
			const frac = (i / numSamples + rotOff) % 1

			var t = frac * 2 * PI
			var x = offX
			var y = offY
			for (const { r, k } of epicycles) {
				x += r(frac) * cos(k(frac) * t)
				y += r(frac) * sin(k(frac) * t)
			}
			points.push({ pt: createVector(x, y) })
		}
		return smoothLoop(points)
	},

	triangle: () => {
		var points = []
		var off = random(TWO_PI)
		var r = random(0.25, 0.425)
		for (let i = 0; i < 3; i++) {
			points.push({
				pt: createVector(
					width*r*cos(i/3*TWO_PI+off),
					width*r*sin(i/3*TWO_PI+off),
				),
			})
		}
		return smoothLoop(points, 0.1)
	},

	circle: () => {
		var points = []
		var r = random(0.25, 0.35)
		for (let i = 0; i < 12; i++) {
			points.push({
				pt: createVector(
					width*r*cos(i/12*TWO_PI),
					width*r*sin(i/12*TWO_PI),
				),
			})
		}
		return smoothLoop(points)
	},

	offset: (path) => {
		var offset = createVector(
			random(-75, 75),
			random(-75, 75),
		)
		return path.map(({ pt, left, right }) => ({
			pt: pt.copy().add(offset),
			left: left ? left.copy().add(offset) : undefined,
			right: right ? right.copy().add(offset) : undefined,
		}))
	}
}

function smoothLoop(points, smoothFrac = 1/6) {
	// Add bezier tangent control points to make it smooth
	for (let i = 0; i < points.length; i++) {
		var prev = points[(i - 1 + points.length) % points.length]
		var curr = points[i]
		var next = points[(i + 1) % points.length]
		var tangent = next.pt.copy().sub(prev.pt).mult(smoothFrac)
		curr.left = curr.pt.copy().sub(tangent)
		curr.right = curr.pt.copy().add(tangent)
	}
	// Make it join up
	points.push(points[0])
	return points
}

// === Tab: intersections ===
function pathIntersections(paths, sampleDistance = 5) {
	const pathGraph = []
	for (let i = 0; i < paths.length; i++) {
		for (let j = i; j < paths.length; j++) {
			pathGraph[i] = pathGraph[i] || []
			pathGraph[j] = pathGraph[j] || []
			if (j === i) {
				pathGraph[i][j] = bezierSelfIntersections(paths[i], sampleDistance)
			} else {
				[pathGraph[i][j], pathGraph[j][i]] = bezierIntersections(paths[i], paths[j], sampleDistance)
			}
		}
	}

	const orderedIntersections = pathGraph
		.map((intersections, i) => intersections
			.reduce((acc, next) => acc.concat(next), [])
			.sort((a, b) => a.distance - b.distance)
		)

	for (const intersections of orderedIntersections) {
		for (let i = 0; i < intersections.length; i++) {
			var curr = intersections[i]
			var prev = intersections[(i - 1 + intersections.length) % intersections.length]
			var next = intersections[(i + 1) % intersections.length]
			curr.next.push(next)
			curr.prev.push(prev)
		}
	}
	const allIntersections = orderedIntersections
		.reduce((a, b) => a.concat(b), [])

	const visit = (node, under) => {
		if (node.visited) return
		node.visited = true
		node.under = under
		visit(node.other, !under)
		for (const neighbour of [...node.next, ...node.prev]) {
			visit(neighbour, !under)
		}
	}

	while (true) {
		const node = allIntersections.find((n) => !n.visited)
		if (!node) break
		visit(node, false)
	}

	return paths.map((path, i) => ({
		path,
		intersections: orderedIntersections[i]
	}))
}

function bezierSelfIntersections(a, sampleDistance = 5) {
	const polyA = polySample(a, sampleDistance)

	const intersections = []

	for (let i = 1; i < polyA.length; i++) {
		for (let j = i + 2; j < polyA.length; j++) {
			const intersectionPoint = lineSegmentIntersection(
				polyA[i - 1].point,
				polyA[i].point,
				polyA[j - 1].point,
				polyA[j].point,
			)
			if (!intersectionPoint) continue
			const ptA = { prev: [], next: [], path: a }
			const ptB = { prev: [], next: [], path: a }
			for (const { from, to, result } of [
				{ from: polyA[i - 1], to: polyA[i], result: ptA },
				{ from: polyA[j - 1], to: polyA[j], result: ptB },
			]) {
				var t = intersectionPoint.dist(from.point) / from.point.dist(to.point)
				var distance = lerp(from.distance, to.distance, t)
				result.distance = distance
			}
			const tangentI = a.getTangentAtLength(ptA.distance)
			const tangentJ = a.getTangentAtLength(ptB.distance)
			const dot = createVector(tangentI.x, tangentI.y).normalize().dot(
				createVector(tangentJ.x, tangentJ.y).normalize(),
			)
			ptA.other = ptB
			ptB.other = ptA
			ptA.dot = dot
			ptB.dot = dot
			intersections.push(ptA)
			intersections.push(ptB)
		}
	}

	return intersections
}

function bezierIntersections(a, b, sampleDistance = 5) {
	var polyA = polySample(a, sampleDistance)
	const polyB = polySample(b, sampleDistance)

	const intersectionsA = []
	const intersectionsB = []

	for (let i = 1; i < polyA.length; i++) {
		for (let j = 1; j < polyB.length; j++) {
			var intersectionPoint = lineSegmentIntersection(
				polyA[i - 1].point,
				polyA[i].point,
				polyB[j - 1].point,
				polyB[j].point,
			)
			if (!intersectionPoint) continue
			var ptA = { prev: [], next: [], path: a }
			var ptB = { prev: [], next: [], path: b }
			for (const { from, to, result } of [
				{ from: polyA[i - 1], to: polyA[i], result: ptA },
				{ from: polyB[j - 1], to: polyB[j], result: ptB },
			]) {
				var t = intersectionPoint.dist(from.point) / from.point.dist(to.point)
				var distance = lerp(from.distance, to.distance, t)
				result.distance = distance
			}
			var tangentI = a.getTangentAtLength(ptA.distance)
			var tangentJ = b.getTangentAtLength(ptB.distance)
			var dot = createVector(tangentI.x, tangentI.y).normalize().dot(
				createVector(tangentJ.x, tangentJ.y).normalize(),
			)
			ptA.dot = dot
			ptB.dot = dot
			ptA.other = ptB
			ptB.other = ptA
			intersectionsA.push(ptA)
			intersectionsB.push(ptB)
		}
	}

	return [intersectionsA, intersectionsB]
}

function polySample(path, sampleDistance) {
	var numSamples = Math.max(2, Math.ceil(path.getTotalLength() / sampleDistance))
	const samples = []
	for (let i = 0; i < numSamples; i++) {
		var distance = i / (numSamples - 1) * path.getTotalLength()
		const rawPoint = path.getPointAtLength(distance)
		const point = createVector(rawPoint.x, rawPoint.y)
		samples.push({ distance, point })
	}

	return samples
}

function lineSegmentIntersection(aFrom, aTo, bFrom, bTo) {
	// Bounding box check
	/*const minAX = Math.min(aFrom.x, aTo.x)
	const maxAX = Math.max(aFrom.x, aTo.x)
	const minAY = Math.min(aFrom.y, aTo.y)
	const maxAY = Math.max(aFrom.y, aTo.y)
	const minBX = Math.min(bFrom.x, bTo.x)
	const maxBX = Math.max(bFrom.x, bTo.x)
	const minBY = Math.min(bFrom.y, bTo.y)
	const maxBY = Math.max(bFrom.y, bTo.y)
	if (Math.max(minAX, minBX) > Math.min(maxAX, maxBX) || Math.max(minAY, minBY) > Math.min(maxAY, maxBY)) {
		return undefined
	}*/

  const det =
    (aTo.x - aFrom.x) * (bTo.y - bFrom.y) -
    (bTo.x - bFrom.x) * (aTo.y - aFrom.y)
  if (det === 0) {
    // Lines are parallel
    return undefined
  } else {
    const lambda =
      ((bTo.y - bFrom.y) * (bTo.x - aFrom.x) +
        (bFrom.x - bTo.x) * (bTo.y - aFrom.y)) /
      det
    const gamma =
      ((aFrom.y - aTo.y) * (bTo.x - aFrom.x) +
        (aTo.x - aFrom.x) * (bTo.y - aFrom.y)) /
      det
    if (0 < lambda && lambda < 1 && 0 < gamma && gamma < 1) {
      return aFrom.copy().add(aTo.copy().sub(aFrom).mult(lambda))
    } else {
      return undefined
    }
  }
}

// === Tab: Ease ===
// Some easing functions
window.Ease = {
  // no easing, no acceleration
  linear: t => t,
  // accelerating from zero velocity
  easeInQuad: t => t*t,
  // decelerating to zero velocity
  easeOutQuad: t => t*(2-t),
  // acceleration until halfway, then deceleration
  easeInOutQuad: t => t<.5 ? 2*t*t : -1+(4-2*t)*t,
  // accelerating from zero velocity 
  easeInCubic: t => t*t*t,
  // decelerating to zero velocity 
  easeOutCubic: t => (--t)*t*t+1,
  // acceleration until halfway, then deceleration 
  easeInOutCubic: t => t<.5 ? 4*t*t*t : (t-1)*(2*t-2)*(2*t-2)+1,
  // accelerating from zero velocity 
  easeInQuart: t => t*t*t*t,
  // decelerating to zero velocity 
  easeOutQuart: t => 1-(--t)*t*t*t,
  // acceleration until halfway, then deceleration
  easeInOutQuart: t => t<.5 ? 8*t*t*t*t : 1-8*(--t)*t*t*t,
  // accelerating from zero velocity
  easeInQuint: t => t*t*t*t*t,
  // decelerating to zero velocity
  easeOutQuint: t => 1+(--t)*t*t*t*t,
  // acceleration until halfway, then deceleration 
  easeInOutQuint: t => t<.5 ? 16*t*t*t*t*t : 1+16*(--t)*t*t*t*t,
  easeInElastic: t => {
    const c4 = (2 * Math.PI) / 3

    return t === 0
      ? 0
      : t === 1
      ? 1
      : -Math.pow(2, 10 * t - 10) * Math.sin((t * 10 - 10.75) * c4)
  },
  easeOutElastic: t => {
    var c4 = (2 * Math.PI) / 3
    return t === 0
      ? 0
      : t === 1
      ? 1
      : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1
  },

  easeInOutElastic: t => {
    var s = 2 * t - 1 // remap: [0,0.5] -> [-1,0]
    var k = ((80 * s - 9) * Math.PI) / 18 // and    [0.5,1] -> [0,+1]
    if (s < 0) return -0.5 * Math.pow(2, 10 * s) * Math.sin(k)
    else return 1 + 0.5 * Math.pow(2, -10 * s) * Math.sin(k)
  },
}

